import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC10%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E8%BF%9B%E5%BA%A6%E7%AE%A1%E7%90%86/","title":"第10章 项目进度管理","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第10章 项目进度管理/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第10章-项目进度管理" tabindex="-1"><a class="header-anchor" href="#第10章-项目进度管理"><span>第10章 项目进度管理</span></a></h1><h2 id="本章概览" tabindex="-1"><a class="header-anchor" href="#本章概览"><span>本章概览</span></a></h2><p>本章介绍项目进度管理的概念、关键路径法以及进度压缩的方法。</p><p><strong>重点知识点：</strong></p><ul><li>进度计划的制定</li><li>关键路径法（CPM）</li><li>进度压缩技术</li><li>进度控制方法</li></ul><hr><h2 id="_10-1-进度计划" tabindex="-1"><a class="header-anchor" href="#_10-1-进度计划"><span>10.1 进度计划</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>进度计划是指确定项目活动的顺序、持续时间和资源需求的过程。</p><h3 id="主要步骤" tabindex="-1"><a class="header-anchor" href="#主要步骤"><span>主要步骤</span></a></h3><ul><li>活动定义</li><li>活动排序</li><li>活动历时估算</li><li>进度计划编制</li></ul><h3 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h3><ul><li>进度计划的编制步骤</li><li>活动历时估算方法</li></ul><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>定义排序估算编制，进度计划四步骤</p><hr><h2 id="_10-2-关键路径法" tabindex="-1"><a class="header-anchor" href="#_10-2-关键路径法"><span>10.2 关键路径法</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>关键路径法是一种用于确定项目最短工期的方法，通过分析活动之间的依赖关系，找出最长的路径。</p><h3 id="关键概念" tabindex="-1"><a class="header-anchor" href="#关键概念"><span>关键概念</span></a></h3><ul><li>关键路径</li><li>总浮动时间</li><li>自由浮动时间</li></ul><h3 id="关键考点-1" tabindex="-1"><a class="header-anchor" href="#关键考点-1"><span>关键考点</span></a></h3><ul><li>关键路径的定义</li><li>总浮动时间和自由浮动时间的区别</li></ul><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>关键路径最长，浮动时间决定灵活性</p><hr><h2 id="_10-3-进度压缩" tabindex="-1"><a class="header-anchor" href="#_10-3-进度压缩"><span>10.3 进度压缩</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><p>进度压缩是指在不改变项目范围的前提下，缩短项目工期的方法。</p><h3 id="压缩方法" tabindex="-1"><a class="header-anchor" href="#压缩方法"><span>压缩方法</span></a></h3><ul><li>赶工</li><li>快速跟进</li></ul><h3 id="关键考点-2" tabindex="-1"><a class="header-anchor" href="#关键考点-2"><span>关键考点</span></a></h3><ul><li>赶工和快速跟进的区别</li><li>进度压缩的风险</li></ul><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>赶工加资源，快速跟进并行做</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};